name: Infra Auto Remediation

on:
  workflow_dispatch:
    inputs:
      alert_id:
        description: 'Alert ID'
        required: true
      dedup_alias:
        description: 'Dedup alias'
        required: true
  repository_dispatch:
    types: [infra-alert]

permissions:
  contents: read
  issues: write
  actions: read
  checks: write

jobs:
  auto_remediation:
    runs-on: ubuntu-latest
    concurrency:
      group: infra-auto-remediation
      cancel-in-progress: false

    steps:
      - name: Checkout repository
        uses: actions/checkout@v4

      - name: Set environment variables
        run: |
          echo "ALERT_ID=${{ github.event_name == 'workflow_dispatch' && github.event.inputs.alert_id || github.event.client_payload.alert_id }}" >> $GITHUB_ENV
          echo "DEDUP_ALIAS=${{ github.event_name == 'workflow_dispatch' && github.event.inputs.dedup_alias || github.event.client_payload.dedup_alias }}" >> $GITHUB_ENV

      - name: Check rate limits and repeated alerts
        id: check
        uses: actions/github-script@v6
        with:
          script: |
            const now = new Date();
            const fiveMinAgo = new Date(now.getTime() - 5 * 60 * 1000);
            const oneHourAgo = new Date(now.getTime() - 60 * 60 * 1000);

            // List recent workflow runs
            const runs = await github.paginate(
              github.rest.actions.listWorkflowRuns,
              {
                owner: context.repo.owner,
                repo: context.repo.repo,
                workflow_id: context.workflow.id,
                status: 'completed',
                per_page: 100
              },
              (response) => response.data.workflow_runs
            );

            const recentRuns = runs.filter(r => new Date(r.created_at) > fiveMinAgo);
            const hourRuns = runs.filter(r => new Date(r.created_at) > oneHourAgo);

            if (recentRuns.length > 0) {
              core.setFailed('5‑minute cooldown active. Skipping run.');
            }
            if (hourRuns.length >= 10) {
              core.setFailed('Hourly cap reached. Skipping run.');
            }

            // Check for repeated alerts
            const dedup = process.env.DEDUP_ALIAS;
            if (!dedup) {
              core.setOutput('repeat', 'false');
              return;
            }

            const issues = await github.paginate(
              github.rest.issues.listForRepo,
              {
                owner: context.repo.owner,
                repo: context.repo.repo,
                state: 'open',
                labels: 'infra-alert',
                per_page: 100
              },
              (response) => response.data
            );

            const repeat = issues.some(issue => issue.title.includes(dedup));
            core.setOutput('repeat', repeat ? 'true' : 'false');

            if (repeat) {
              core.setFailed('Repeated alert detected. Creating needs‑human issue.');
            }

      - name: Create needs‑human issue for repeated alert
        if: steps.check.outputs.repeat == 'true'
        uses: actions/github-script@v6
        with:
          script: |
            const title = `⚠️ Needs Human Attention: Infra Alert ${process.env.ALERT_ID}`;
            const body = `A repeated alert with dedup alias **${process.env.DEDUP_ALIAS}** was detected. Please investigate manually.`;
            await github.rest.issues.create({
              owner: context.repo.owner,
              repo: context.repo.repo,
              title,
              body,
              labels: ['infra-alert', 'needs-human']
            });

      - name: Skip remaining steps on repeated alert
        if: steps.check.outputs.repeat == 'true'
        run: exit 0

      - name: Investigate alert
        id: investigate
        run: |
          echo "Running investigation script..."
          # Placeholder for actual investigation logic
          echo "Alert ID: ${{ env.ALERT_ID }}" >> findings.txt
          echo "Dedup alias: ${{ env.DEDUP_ALIAS }}" >> findings.txt
          # Simulate findings
          echo "Findings: All systems nominal." >> findings.txt

      - name: Post findings to Discord
        uses: peter-evans/webhook@v1
        with:
          url: ${{ secrets.DISCORD_WEBHOOK_URL }}
          content: |
            **Infra Auto Remediation**  
            Alert ID: ${{ env.ALERT_ID }}  
            Dedup alias: ${{ env.DEDUP_ALIAS }}  
            Findings:  
            ```
            $(cat findings.txt)
            ```

      - name: Create GitHub issue for alert
        uses: actions/github-script@v6
        with:
          script: |
            const title = `Infra Alert: ${process.env.ALERT_ID}`;
            const body = `**Alert ID:** ${process.env.ALERT_ID}\n\n**Dedup alias:** ${process.env.DEDUP_ALIAS}\n\n**Findings:**\n\`\`\`\n${await github.utils.readFile('findings.txt')}\n\`\`\``;
            await github.rest.issues.create({
              owner: context.repo.owner,
              repo: context.repo.repo,
              title,
              body,
              labels: ['infra-alert']
            });
